INSERT INTO skills (id, user_id, name, description, icon, steps, inputs, output, directive, sort_order) VALUES
 ('c0000000-0000-4000-8000-000000000011', NULL, 'ตัวอย่างหนังกำลังภายใน (ตัดเร็วแบบหนังโรง)', 'โครงตัวอย่างหนัง 3 องก์ ตัดภาพทุก 1.5–3 วินาทีด้วยคลิปหลายช็อต ฉากต่อสู้ช็อตละหนึ่งท่าแบบความเร็วจริง บทพูดสั้นแยกช็อตโคลสอัพ เสียงประกอบสมจริง ไม่ใส่เพลงในคลิป', 'clapperboard',
  '["องก์ 1 โลกและบาดแผล: ภาพกว้างเปิดเรื่อง ความสูญเสีย สีหน้าตัวเอก","องก์ 2 ความขัดแย้ง: ฝึก/ไล่ล่า เปิดตัวผู้ร้ายมุมต่ำ ปะทะครั้งแรก","องก์ 3 จุดพีค: ตัดเร็วที่สุด ค้างที่สีหน้า แล้วปิดด้วยช็อตสุดท้าย","ต่อสู้: ช็อตละหนึ่งท่า ตัดกลางท่า ฟันแล้วตัดไปปฏิกิริยาอีกมุม"]', '["character"]', 'film',
  'Theatrical wuxia trailer, cut like a big-studio Chinese fantasy trailer (median shot about 1.5 s). Three acts plus a button. Act 1, the world and the wound: one epic establishing wide, the loss (a burning sect, a fallen master), the hero''s face reacting in close-up. Act 2, rising conflict: training or pursuit, the villain revealed from a low angle, first clashes, a short line between moments. Act 3, the climax: the fastest cutting and the best action, then a held beat on the hero''s face, then a 2-3 s button (one last strike or a look). Build everything except dialogue from multi-shot clips of 4-6 cuts of 1.5-3 s; each cut is one clear image: an extreme wide for scale, a close-up face, an insert (hand on the hilt, blade edge, embers, rain on steel) or one action fragment. Fights: one move per cut at real speed, cut mid-move, the strike in one cut and the reaction from a new angle in the next; low angle for the hero''s power, high angle for the fallen; leaps are brief and end in a landing with weight. Camera: static or a slow push on wides, fast handheld only inside action, never orbit. Dialogue: 2-3 lines of at most 12 Thai characters, each in its own single close-up, face three-quarter, head up, clear firm voice. Sound: real foley only (dry steel ring, blade cutting air, cloth whoosh, footsteps, fire crackle, rain); no music in the clips, the music bed is added in the edit.', 20)
ON CONFLICT (id) DO NOTHING;
COMMIT;
